function CatHouseCultivationPopup:OnFocus(focus)

    if focus then
        GameUtils.UpdateNavBarShowGoods({ 300002, self.hatchConsumeId, self.rallyGoodsId }, true)
        if not self.isInit then
            KTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, false)
            CfUtils.SetTopActive(false)

            local name, isShow
            local resetFlag = KCookie.Get(CookieCultivationResetCameraEnter)
            if resetFlag then
                --- 1. 清理cookie
                KCookie.Set(CookieCultivationResetCameraEnter)
                --- 2. self.cameraName2Go 原先显示的 go 置为false
                local enterGo = self.cameraName2Go[VirtualCameraNameEnter]
                if enterGo then
                    KTool.SetActive(enterGo, false)
                end
                name = VirtualCameraNameEnter
                isShow = true

            elseif self.isEnterSign then
                name = VirtualCameraNameSignup
                isShow = false
                self.isEnterSign = nil
            end
            KTool.SetActive(self.Root.gameObject, true)
            if name then
                self:SwitchVirtualCameraShowState(name, isShow, function()
                    self:InitServerCache()
                    self:FreshUI()
                    self:AddListener()
                    CfUtils.SetTopActive(true)
                    KTool.SetActive(self.controller.gameObject, true)
                end)
            else
                self:InitServerCache()
                self:FreshUI()
                self:AddListener()
                CfUtils.SetTopActive(true)
                KTool.SetActive(self.controller.gameObject, true)
            end

        else
            self.isInit = false
        end
    else
        GameUtils.RestoreHealthNodes()
        KTool.SetActive(self.controller.gameObject, false)
    end
end

function CatHouseCultivationPopup:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            CfUtils.SetTopActive(false)
            -- self.oldShowLoadedScenesState = SceneManagementIns:GetShowLoadedScenesState()

            local catHouseMgr = CatHouseMgr:GetInstance()
            while catHouseMgr:GetSceneCo(SceneId) ~= nil do
                cs_coroutine.yield_return()
            end
            local CatNodeGroup = self.CatNodeGroup
            ---@type SceneInstance
            local sceneInstance = SceneManagementIns:GetSceneInstance(SceneId)
            local Box = sceneInstance:GetCacheObjectByName("Box")
            local childCount = CatNodeGroup.transform.childCount
            for i = 2, childCount do
                local gameObject = Box.transform:Find(string.format("%s/100_categg_paperbag", i)).gameObject
                self.coverNodes[i] = gameObject:GetComponent(AnimatorType)
                local cultivationType = self.deliveryId2CultivationType[i]
                KTool.SetActive(self.coverNodes[i].gameObject, cultivationType == CultivationType.Lock)
            end

            if childCount > self.upLimit then
                for i = self.upLimit + 1, childCount do
                    local catNode = CatNodeGroup:GetChild(i - 1)
                    KTool.SetActive(catNode.gameObject, false)
                    KTool.SetActive(self.coverNodes[i].gameObject, true)

                end

            end

            --coroutine.yield(SceneManagementIns:AppendScene(Constants.IdSceneSetting23, false))
            SceneManagementIns:SetActive(SceneId, true)
            local CameraGo = sceneInstance:GetCacheObjectByName("Camera")
            KTool.GetOrAddComponent(CameraGo.gameObject, URPBaseCameraType)
            cs_coroutine.yield_return()

            self.virtualCameraGo = sceneInstance:GetCacheObjectByName("VirtualCamera")

            cs_coroutine.yield_return(self:SwitchVirtualCameraShowState(VirtualCameraNameEnter, true))

            CfUtils.SetTopActive(true)
            local IncubationPos = sceneInstance:GetCacheObjectByName("IncubationPos")
            local localPosition = IncubationPos.transform.localPosition
            IncubationPos.transform.localPosition = Vector3.New(localPosition.x, 0.02, localPosition.z)
            local modelPosNodes = {}
            for i = 1, self.upLimit do
                modelPosNodes[i] = IncubationPos.transform:Find(string.format("Seat%s", i))
                local catNode = CatNodeGroup:GetChild(i - 1)
                self.catNodes[i] = catNode
                
            end

            self.modelPosNodes = modelPosNodes

            --self:InitUI()

            if self.deliveryId then
                ---al catHouseHomeDojo = component:GetCatHouseHomeDojo()
                local deliveryId = self.deliveryId

                --- 坑位处于好友请求中或者坑位无
                if self.deliveryId2CultivationType[deliveryId] then
                    KTool.SetActive(self.Root.gameObject, false)
                    self:EnterMatchView(self.deliveryId, self.isFromInteraction)
                end

                self.deliveryId = nil
                self.isFromInteraction = nil
            end
        end)
    end))
    return coWait
end

