function CatHouseCultivationPopup:InitData()
    -----------------------------
    ---配表相关
    --- 孵化空位上限 不包含特权卡上限
    local upLimit = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.HatchUpLimit).num)
    --- 孵化每次扩充消耗道具id
    local goodsId = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.HatchExpansionConsumeId).num)
    --- 孵化每次扩充消耗道具数量
    local goodsNum = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.HatchExpansionConsumeNum).num)

    local privilegeRewardsSetting = CfUtils.GetCf(AutoIds.IdSetting1908, "CatHousePrivilegeRewardsVo")
    ---@type CatHousePrivilegeRewardsVo[]
    local privilegeRewardsVos = privilegeRewardsSetting:GetAll()
    local privilegeSeatNum2Vo = {}
    for i, v in pairs(privilegeRewardsVos) do
        if v.seatNum > 0 then
            privilegeSeatNum2Vo[v.seatNum] = v
            upLimit = upLimit + 1
        end
    end

    -----------------------------
    ---检查是否存在 培育id  存在则需要在镜头移动完成后 进入配对界面
    local Argument = self.controller.Argument
    if not isNull(Argument) then
        local parameters = Argument.parameters
        if not isNull(parameters) then
            self.deliveryId = parameters.deliveryId
            self.isFromInteraction = parameters.isFromInteraction
            parameters.deliveryId = nil
            parameters.isFromInteraction = nil
        end
    end

    self.goodsId             = goodsId
    self.goodsNum            = goodsNum
    self.upLimit             = upLimit
    self.privilegeSeatNum2Vo = privilegeSeatNum2Vo

    self.rallyGoodsId = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.RallyGoodsId).num)
    self.hatchConsumeId = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.HatchConsumeId).num)
    
end

function CatHouseCultivationPopup:InitServerCache()
    -----------------------------
    ---server相关
    ---@type CatHouseComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)

    ---@type CatHouseHomeDojo
    local homeDojo     = component:GetCatHouseHomeDojo()
    local deliveryList = checkTable(homeDojo.deliveryList)
    
    local deliveryId2Data = {}
    for i, v in pairs(deliveryList) do
        local deliveryId = checkNumber(v.deliveryId)
        deliveryId2Data[deliveryId] = v

    end
    self.deliveryId2Data = deliveryId2Data

    local deliveryId2CultivationType = {}
    for deliveryId = 1, self.upLimit do
        local cultivationType = self:InitCultivationType(deliveryId2Data[deliveryId], deliveryId, self.privilegeSeatNum2Vo[deliveryId])
        deliveryId2CultivationType[deliveryId] = cultivationType
    end
    self.deliveryId2CultivationType = deliveryId2CultivationType

end

---InitCultivationTyp
---@param deliveryData table   培育数据
---@param deliveryId   number  培育id
---@param privilegeRewardsVo table 特权卡数据
function CatHouseCultivationPopup:InitCultivationType(deliveryData, deliveryId, privilegeRewardsVo)
    local GetCultivationTypeByData = function ()
        local cultivationType
        local status     = deliveryData ~= nil and checkNumber(deliveryData.status)     or CultivationType.Add
        local remainTime = deliveryData ~= nil and checkNumber(deliveryData.remainTime) or 0
        local isTimeEnd  = remainTime == 0
        if status == CultivationType.FriendsConfirming then
            cultivationType =  isTimeEnd and CultivationType.FriendsConfirmingFail or CultivationType.FriendsConfirming

        elseif status == CultivationType.FriendsConfirmingFail then
            cultivationType = CultivationType.FriendsConfirmingFail

        elseif status == CultivationType.Hatching then
            cultivationType = isTimeEnd and CultivationType.Receive or CultivationType.Hatching

        elseif status == CultivationType.RequestFail then
            cultivationType = CultivationType.RequestFail

        else
            cultivationType = CultivationType.Add

        end

        return cultivationType
    end


    local cultivationType
    if privilegeRewardsVo then
        ---@type CatHouseComponent
        local component             = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
        --- 如果是特权位置
        --- 检查是否解锁了特权位置 并且 解锁了特权卡
        local isUnlockPrivilegeCard = component:GetPrivilegeCardSecondsById(privilegeRewardsVo.id) > 0
        if deliveryData then
            cultivationType = GetCultivationTypeByData()
        end
        
        if not isUnlockPrivilegeCard and (cultivationType == nil or cultivationType == CultivationType.Lock or cultivationType == CultivationType.Add) then
            cultivationType = CultivationType.CanLock
        end
        -- print(cultivationType, "-----")
        -- if deliveryData and isUnlockPrivilegeCard then
        -- else
        --     cultivationType = CultivationType.CanLock
        -- end
        -- cultivationType = (deliveryData and component:GetPrivilegeCardSecondsById(privilegeRewardsVo.id) > 0 and checkNumber(deliveryData.status) ~= CultivationType.Add) and GetCultivationTypeByData() or CultivationType.CanLock
    else
        ---@type CatHouseComponent
        local component             = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
        ---@type CatHouseHomeDojo
        local homeDojo              = component:GetCatHouseHomeDojo()
        local maxDeliveryNum        = checkNumber(homeDojo.maxDeliveryNum)
        local nextUnlockDeliveryNum = maxDeliveryNum + 1
        if deliveryId < nextUnlockDeliveryNum then
            ---非特权卡是逐个解锁 deliveryData 不会为空
            cultivationType = GetCultivationTypeByData()

        elseif deliveryId == nextUnlockDeliveryNum then
            cultivationType = CultivationType.CanLock

        else
            cultivationType = CultivationType.Lock

        end
    end

    return cultivationType
end

