function CatHouseCultivationPopup:FreshUI(isRefresh)
    self:FreshAllCatNode(isRefresh, true)
    local component             = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    local seconds               = component:GetPrivilegeCardSecondsById(PrivilegeCardId)
    self:FreshPrivilegeCountdown(seconds)
end

---FreshAllCatNode
function CatHouseCultivationPopup:FreshAllCatNode(isRefresh, isInit)
    for i = 1, self.upLimit do
        local catNode = self.catNodes[i]
        if isInit then
            local offset = CultivationUINodeOffset[i]
            local uiPos  = CfUtils.WorldPosition2UIPosition(self.modelPosNodes[i].transform.position, self.CatNodeGroup)
            catNode.transform.anchoredPosition = Vector2.New(uiPos.x + offset[1], uiPos.y + offset[2])
        end
        self:FreshCatNode(catNode, i, isRefresh)

    end

end

function CatHouseCultivationPopup:FreshCatNode(node, deliveryId, isRefresh, isPlayAnimation)
    if node == nil then return end

    ---@type CatHouseCultivationCatNode
    local env = CfUtils.GetLuaScr(node.gameObject, CatHouseCultivationCatNodeEnvPath)
    if isNull(env) then return end
    xTry(function()
        if not isRefresh then
            env:InitParams(self.privilegeSeatNum2Vo[deliveryId], self.modelPosNodes[deliveryId], self.coverNodes[deliveryId])
        end
        env:FreshUI(self.deliveryId2Data, deliveryId, self.deliveryId2CultivationType)

    end)

end

function CatHouseCultivationPopup:SwitchVirtualCameraShowState(virtualCameraName, isShow, cb)
    UIRaycastBlocker:AddCondition(ConditionSwitchVirtualCamera)
    return cs_coroutine.start(function()
        local gameObject = self.cameraName2Go[virtualCameraName]
        if gameObject == nil then
            local transform = self.virtualCameraGo.transform:Find(virtualCameraName)
            gameObject = transform.gameObject
            self.cameraName2Go[virtualCameraName] = gameObject
        end
        KTool.SetActive(gameObject, isShow)
        cs_coroutine.yield_return()
        local mainCamera = URPCameraController.Instance.mainCamera
        local brain = mainCamera.gameObject:GetComponent(CinemachineBrainType)
        while brain.IsBlending do
            cs_coroutine.yield_return()
        end
        if cb then
            cb()
        end
        UIRaycastBlocker:RemoveCondition(ConditionSwitchVirtualCamera)
    end)
end

function CatHouseCultivationPopup:FreshPrivilegeCountdown(seconds)
    local countdownState = seconds > 0
    local isChange = countdownState ~= self.countdownState
    if isChange then
        self.countdownState = countdownState
        KTool.SetActive(self.Countdown.gameObject, countdownState)
    end
    if countdownState then
        self.CountdownText.text = CfUtils.GetTimeHMS9(seconds)
    end
end

