function CatHouseCultivationPopup:OnEventCatHouseTimeChange()
    local cdCount = 0
    local privilegeSeatNum2Vo = self.privilegeSeatNum2Vo
    ---@type CatHouseComponent
    -- local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    -- local catHouseHomeDojo = component:GetCatHouseHomeDojo()
    for deliveryId, deliveryData in pairs(self.deliveryId2Data) do
        ---@type CatHousePrivilegeRewardsVo
        local vo = privilegeSeatNum2Vo[deliveryId]
        --- 检查特权卡是否过期
        -- if privilegeSeatNum2Vo[deliveryId]
        --         and component:GetPrivilegeCardSecondsById(vo.id) > 0 
        --         and checkNumber(deliveryData.status) == 0 then
        --     self.deliveryId2Data[deliveryId] = nil
        -- end
        local cultivationType = self:InitCultivationType(deliveryData, deliveryId, self.privilegeSeatNum2Vo[deliveryId])
        self.deliveryId2CultivationType[deliveryId] = cultivationType

        self:FreshCatNode(self.catNodes[deliveryId], deliveryId, true)

        if deliveryData.remainTime > 0 then
            cdCount = cdCount + 1
        end
    end

    local component             = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    local seconds               = component:GetPrivilegeCardSecondsById(PrivilegeCardId)
    self:FreshPrivilegeCountdown(seconds)
    --- 检查是否解锁了特权位置 并且 解锁了特权卡
    local isUnlockPrivilegeCard = seconds > 0
    if isUnlockPrivilegeCard then
        cdCount = cdCount + 1
    end

    if cdCount == 0 then
        self:RemoveListener()
    end

end

